'use strict';

// MODULES //

var lowercase = require( '@stdlib/string/base/lowercase' );
var floor = require( '@stdlib/math/base/special/floor' );


// VARIABLES //

var SELECT = 20;


// MAIN //

/**
* Sort a double-precision floating-point strided array in increasing or decreasing order using quicksort, with insertion sort for small partitions (size <= 20).
*
* ## Notes
*
* -   If the operation was successful, the function returns a status code equal to `0`; otherwise, the function returns a status code equal to `-i`, corresponding to the `i`-th argument which had an illegal value.
*
* @private
* @param {string} sortOrder - sort direction
* @param {NonNegativeInteger} N - number of elements to sort
* @param {Float64Array} D - array to sort in-place
* @param {integer} strideD - stride length for `D`
* @param {NonNegativeInteger} offsetD - starting index for `D`
* @param {Float64Array} stack - stack array
* @param {integer} strideStack - stride length for `stack`
* @param {NonNegativeInteger} offsetStack - starting index for `stack`
* @returns {integer} status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var D = new Float64Array( [ 5.0, 7.0, 9.0, 3.0, 11.0 ] );
* var stack = new Float64Array( 64 );
*
* dlasrt( 'I', 5, D, 1, 0, stack, 1, 0 );
* // D => <Float64Array>[ 3, 5, 7, 9, 11 ]
*/
function dlasrt( sortOrder, N, D, strideD, offsetD, stack, strideStack, offsetStack ) {
	var lowerId;
	var stkpnt;
	var start;
	var dmnmx;
	var endd;
	var idx1;
	var idx2;
	var idx3;
	var dir;
	var tmp;
	var d1;
	var d2;
	var d3;
	var i;
	var j;

	// Determine sort direction
	lowerId = lowercase( sortOrder );

	if ( lowerId === 'd' ) {
		dir = 0;
	} else if ( lowerId === 'i' ) {
		dir = 1;
	} else {
		return -1;
	}
	if ( N < 0 ) {
		return -2;
	}
	if ( N <= 1 ) {
		return 0;
	}

	// Initialize the stack with the full range (using 0-based indices)...
	stkpnt = 0;
	stack[ offsetStack ] = 0;
	stack[ offsetStack + strideStack ] = N - 1;

	while ( stkpnt >= 0 ) {
		start = stack[ offsetStack + ( 2 * stkpnt * strideStack ) ];
		endd = stack[ offsetStack + ( 2 * stkpnt * strideStack ) + strideStack ];
		stkpnt -= 1;

		if ( endd - start <= SELECT && endd - start > 0 ) {
			// Insertion sort for small partitions...
			if ( dir === 0 ) {
				// Sort in decreasing order...
				idx1 = offsetD + ( ( start + 1 )*strideD );
				for ( i = start + 1; i <= endd; i++ ) {
					idx2 = idx1; // index of i
					for ( j = i; j >= start + 1; j-- ) {
						idx3 = idx2 - strideD; // index of j - 1
						if ( D[ idx2 ] <= D[ idx3 ] ) {
							break;
						}
						dmnmx = D[ idx2 ];
						D[ idx2 ] = D[ idx3 ];
						D[ idx3 ] = dmnmx;
						idx2 -= strideD;
					}
					idx1 += strideD;
				}
			} else {
			// Sort in increasing order...
				idx1 = offsetD + ( ( start + 1 )*strideD );
				for ( i = start + 1; i <= endd; i++ ) {
					idx2 = idx1; // index of i
					for ( j = i; j >= start + 1; j-- ) {
						idx3 = idx2 - strideD; // index of j - 1
						if ( D[ idx2 ] >= D[ idx3 ] ) {
							break;
						}
						dmnmx = D[ idx2 ];
						D[ idx2 ] = D[ idx3 ];
						D[ idx3 ] = dmnmx;
						idx2 -= strideD;
					}
					idx1 += strideD;
				}
			}
		} else if ( endd - start > SELECT ) {
			// Quicksort partition using median-of-three pivot...
			d1 = D[ offsetD + ( start*strideD ) ];
			d2 = D[ offsetD + ( endd*strideD ) ];
			i = floor( ( start + endd ) / 2 );
			d3 = D[ offsetD + ( i*strideD ) ];

			// Find median of d1, d2, d3...
			if ( d1 < d2 ) {
				if ( d3 < d1 ) {
					dmnmx = d1;
				} else if ( d3 < d2 ) {
					dmnmx = d3;
				} else {
					dmnmx = d2;
				}
			} else if ( d3 < d2 ) {
				dmnmx = d2;
			} else if ( d3 < d1 ) {
				dmnmx = d3;
			} else {
				dmnmx = d1;
			}

			if ( dir === 0 ) {
				// Partition for decreasing order...
				i = start;
				j = endd;
				while ( true ) {
					idx1 = offsetD + ( j*strideD );
					while ( D[ idx1 ] < dmnmx ) {
						idx1 -= strideD;
						j -= 1;
					}

					idx2 = offsetD + ( i*strideD );
					while ( D[ idx2 ] > dmnmx ) {
						idx2 += strideD;
						i += 1;
					}
					if ( i >= j ) {
						break;
					}
					tmp = D[ idx2 ];
					D[ idx2 ] = D[ idx1 ];
					D[ idx1 ] = tmp;
					i += 1;
					j -= 1;
				}
			} else {
				// Partition for increasing order...
				i = start;
				j = endd;
				while ( true ) {
					idx1 = offsetD + ( j*strideD );
					while ( D[ idx1 ] > dmnmx ) {
						idx1 -= strideD;
						j -= 1;
					}

					idx2 = offsetD + ( i*strideD );
					while ( D[ idx2 ] < dmnmx ) {
						idx2 += strideD;
						i += 1;
					}
					if ( i >= j ) {
						break;
					}
					tmp = D[ idx2 ];
					D[ idx2 ] = D[ idx1 ];
					D[ idx1 ] = tmp;
					i += 1;
					j -= 1;
				}
			}

			// Push sub-partitions onto stack (larger first for bounded stack depth)...
			idx1 = offsetStack + ( 2 * stkpnt * strideStack );
			if ( j - start > endd - j - 1 ) {
				stkpnt += 1;
				idx1 += 2 * strideStack;
				stack[ idx1 ] = start;
				stack[ idx1 + 1 ] = j;

				stkpnt += 1;
				idx1 += 2 * strideStack;
				stack[ idx1 ] = j + 1;
				stack[ idx1 + 1 ] = endd;
			} else {
				stkpnt += 1;
				idx1 += 2 * strideStack;
				stack[ idx1 ] = j + 1;
				stack[ idx1 + 1 ] = endd;

				stkpnt += 1;
				idx1 += 2 * strideStack;
				stack[ idx1 ] = start;
				stack[ idx1 + 1 ] = j;
			}
		}
	}
	return 0;
}


// EXPORTS //

module.exports = dlasrt;
